class MinCost {
    public static int minCost(List<List<Integer>> cost, int m, int n) {
        if (cost == null || cost.isEmpty()) {
            return 0;
        }

        int[][] dp = new int[m + 1][n + 1];
        dp[0][0] = cost.get(0).get(0);

        for (int i = 1; i <= m; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        for (int j = 1; j <= n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.min(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        return dp[m][n];
    }
}

